package dk.sdu.cbse.springlab; import org.springframework.context.annotation.*; import java.util.*;
public class Main{public interface Processor{String name();} @ComponentScan static class Config{} @org.springframework.stereotype.Component static class PlayerProcessor implements Processor{public String name(){return "PlayerProcessor";}} @org.springframework.stereotype.Component static class Game{private final List<Processor> processors; Game(List<Processor> p){processors=p;}void run(){processors.forEach(x->System.out.println("Injected: "+x.name()));}} public static void main(String[] a){try(var c=new AnnotationConfigApplicationContext(Config.class)){c.getBean(Game.class).run();}}}
